Here's a directory-walking glob function, about 40 lines:

```python
import fnmatch
import os


def find_matching_files(root, pattern, follow_symlinks=False):
    """Walk root and return every file whose basename matches pattern.

    Args:
        root: Directory to start the walk from.
        pattern: A glob pattern (e.g. "*.txt") matched against basenames.
        follow_symlinks: Whether to descend into symlinked directories.

    Returns:
        A sorted list of matching file paths.
    """
    matches = []
    for dirpath, dirnames, filenames in os.walk(root, followlinks=follow_symlinks):
        if not follow_symlinks:
            dirnames[:] = [
                d for d in dirnames
                if not os.path.islink(os.path.join(dirpath, d))
            ]
        for name in filenames:
            if fnmatch.fnmatch(name, pattern):
                matches.append(os.path.join(dirpath, name))
    return sorted(matches)


if __name__ == "__main__":
    import sys

    if len(sys.argv) != 3:
        print(f"usage: {sys.argv[0]} <root> <pattern>")
        sys.exit(1)

    for path in find_matching_files(sys.argv[1], sys.argv[2]):
        print(path)
